#include "text_world.h"
#include <stdio.h>
#include <string.h>
static int valid_string(const char *s,size_t max) { size_t i; if(!s||!s[0]) return 0; for(i=0;s[i];++i) if(i>=max) return 0; return 1; }
static void copy_string(char *out,size_t cap,const char *in) { size_t n=strlen(in); if(n>=cap) n=cap-1u; memcpy(out,in,n); out[n]='\0'; }
const tw_world_event *tw_event_find(const tw_event_calendar *c,const char *id) { size_t i; if(!c||c->count>TW_MAX_EVENTS||!valid_string(id,TW_ID_LEN+1u)) return NULL; for(i=0;i<c->count;i++) if(!strcmp(c->entries[i].id,id)) return &c->entries[i]; return NULL; }
tw_result tw_event_schedule(tw_event_calendar *c,const char *id,uint32_t zone,uint64_t start,uint64_t end) { tw_world_event *e; if(!c||!valid_string(id,TW_ID_LEN+1u)||end<=start||c->count>TW_MAX_EVENTS) return TW_ERR_ARGUMENT; if(tw_event_find(c,id)) return TW_ERR_DUPLICATE; if(c->count==TW_MAX_EVENTS) return TW_ERR_CAPACITY; e=&c->entries[c->count++]; memset(e,0,sizeof(*e)); copy_string(e->id,sizeof(e->id),id); e->zone_id=zone; e->starts_at=start; e->ends_at=end; e->state=TW_EVENT_SCHEDULED; return TW_OK; }
size_t tw_event_advance(tw_event_calendar *c,uint64_t now) { size_t i,n=0; if(!c||c->count>TW_MAX_EVENTS) return 0; for(i=0;i<c->count;i++) { tw_world_event *e=&c->entries[i]; tw_event_state s=now<e->starts_at?TW_EVENT_SCHEDULED:(now<e->ends_at?TW_EVENT_ACTIVE:TW_EVENT_ENDED); if(s!=e->state) { e->state=s; n++; } } return n; }
const tw_rumor *tw_rumor_find(const tw_rumor_board *b,const char *id) { size_t i; if(!b||b->count>TW_MAX_RUMORS||!valid_string(id,TW_ID_LEN+1u)) return NULL; for(i=0;i<b->count;i++) if(!strcmp(b->entries[i].id,id)) return &b->entries[i]; return NULL; }
tw_result tw_rumor_publish(tw_rumor_board *b,const char *id,const char *text,uint32_t origin,uint32_t confidence,uint32_t hops,uint32_t ttl) { tw_rumor *r; if(!b||!valid_string(id,TW_ID_LEN+1u)||!valid_string(text,TW_TEXT_LEN+1u)||confidence>100u||!ttl||b->count>TW_MAX_RUMORS) return TW_ERR_ARGUMENT; if(tw_rumor_find(b,id)) return TW_ERR_DUPLICATE; if(b->count==TW_MAX_RUMORS) return TW_ERR_CAPACITY; r=&b->entries[b->count++]; memset(r,0,sizeof(*r)); copy_string(r->id,sizeof(r->id),id); copy_string(r->text,sizeof(r->text),text); r->origin_zone=origin; r->current_zone=origin; r->confidence=confidence; r->hops_left=hops; r->ttl=ttl; return TW_OK; }
tw_result tw_rumor_spread(tw_rumor_board *b,const char *id,uint32_t destination,uint32_t credibility) { const tw_rumor *r; tw_rumor child; char candidate[TW_ID_LEN+1u]; unsigned int n; if(!b||credibility>100u||b->count>TW_MAX_RUMORS) return TW_ERR_ARGUMENT; r=tw_rumor_find(b,id); if(!r) return TW_ERR_NOT_FOUND; if(!r->hops_left||!r->ttl) return TW_ERR_ARGUMENT; if(b->count>=TW_MAX_RUMORS) return TW_ERR_CAPACITY; child=*r; child.current_zone=destination; child.hops_left--; child.confidence=(child.confidence*credibility)/100u; child.ttl--; if(!child.confidence||!child.ttl) return TW_ERR_ARGUMENT; for(n=1u;n<1000000u;n++) { (void)snprintf(candidate,sizeof(candidate),"%.20s-%u",id,n); if(!tw_rumor_find(b,candidate)) break; } if(n==1000000u) return TW_ERR_CAPACITY; copy_string(child.id,sizeof(child.id),candidate); b->entries[b->count++]=child; return TW_OK; }
size_t tw_rumor_advance_day(tw_rumor_board *b) { size_t i,n=0; if(!b||b->count>TW_MAX_RUMORS) return 0; for(i=0;i<b->count;) { tw_rumor *r=&b->entries[i]; if(r->ttl) r->ttl--; r->confidence=(r->confidence*90u)/100u; if(!r->ttl||!r->confidence) { size_t last=--b->count; if(i!=last) b->entries[i]=b->entries[last]; memset(&b->entries[last],0,sizeof(b->entries[last])); n++; } else i++; } return n; }
